 void timerCallback() override {if(watchDevices)deviceMonitor.tick(deviceDialog!=nullptr);bool edit=!e.enabled.load()&&!e.transport.isPlaying()&&!e.multitrack.active();addTrack.setEnabled(edit);deleteTrack.setEnabled(edit&&!strips.isEmpty());auto inputs=activeInputs();for(auto* s:strips)s->refreshInputs(inputs);if(live.getToggleState()!=e.enabled.load()){live.setToggleState(e.enabled.load(),dontSendNotification);live.setButtonText(e.enabled.load()?"LIVE ON":"LIVE OFF");}if(dashboard.isVisible())dashboard.refresh();if(matrix.isVisible())matrix.refresh();if(audioDevicePage.isVisible())audioDevicePage.refresh();if(externalPage.isVisible())externalPage.refresh();if(inspector.isVisible())inspector.refresh();if(rackPanel.isVisible())rackPanel.refresh();if(mastering.isVisible())mastering.refresh();if(recordInfo.isVisible()){recordInfo.setText((e.multitrack.active()?String("Recording raw inputs"):String("Input capture idle"))+" | errors "+String((int)e.multitrack.missedBlocks.load()),dontSendNotification);recordInputs.setEnabled(!e.multitrack.active());}if(broadcastPage.isVisible())broadcastPage.refresh();if(aiPage.isVisible())aiPage.refresh(mode.getSelectedId());analyticsPage.refresh();monitor.mixMode=mode.getSelectedId();for(int b=0;b<4;++b)monitor.names[b]=customNames[b];if(monitor.isVisible())monitor.repaint();auto* device=e.devices.getCurrentAudioDevice();deviceMetrics.setText(device?String(device->getCurrentSampleRate()/1000,1)+" kHz | CPU "+String(e.devices.getCpuUsage()*100,0)+"%":"Audio offline",dontSendNotification);transportTime.setText(String(e.transport.getCurrentPosition(),2)+" s",dontSendNotification);if(arrangement.isVisible())arrangement.repaint();bool active=e.enabled.load() && e.devices.getCurrentAudioDevice()!=nullptr && e.peak.load()<0.9f; bool anySolo=false; for(auto& c:e.ch) anySolo|=c.solo.load(); for(int b=0;b<B;++b)busLabels[b].setText(customNames[b]+"  "+String(Decibels::gainToDecibels(e.busPeak[b].load()),1)+" dBFS",dontSendNotification);for(auto* s:strips){s->updateAuto(mode.getSelectedId(),active && !anySolo);if(s->isShowing())s->repaint();}int unmuted=0; for(auto& c:e.ch) if(!c.mute.load()) ++unmuted; routeStatus.setText(!e.started?"Open Audio setup first":!e.enabled.load()?"Live inputs OFF - enable monitoring with headphones":unmuted==0?"All channels muted - unmute one input":anySolo?"Auto paused: solo active":e.peak.load()>=0.9f?"Auto paused: high master peak":mode.getSelectedId()==1?"Manual mixing":"Auto ready | Green meter: input / Blue: post fader",dontSendNotification);status.setText("v0.19.0 | "+(!e.started ? String("Audio not started - open Audio setup | ") : e.deviceError.isNotEmpty() && e.devices.getCurrentAudioDevice()==nullptr ? e.deviceError+" | " : String())+"Device CPU: "+String(e.devices.getCpuUsage()*100,1)+"%  |  Master peak: "+String(Decibels::gainToDecibels(e.peak.load()),1)+" dBFS | Write failures: "+String((int)e.missedWrites.load()),dontSendNotification);}
